/* Local-only real API lab. Financial mutations always use existing services/routes.
 * Provisions a NEW disposable PostgreSQL database and dedicated Redis container.
 * No production target option; database/container names are generated by this script. */
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const { randomUUID, createHash } = require('node:crypto');
const root = path.resolve(__dirname, '..');
if (fs.existsSync(path.join(root, '.env')))
  process.loadEnvFile(path.join(root, '.env'));
const originalUrl = new URL(process.env.DATABASE_URL);
if (!['localhost', '127.0.0.1'].includes(originalUrl.hostname))
  throw new Error('Lab requires local PostgreSQL');
const run = randomUUID().replaceAll('-', '').slice(0, 10);
const database = `ggvault_phase7_${run}`;
const redisName = `ggvault-phase7-${run}`;
const output = path.join(root, '.cache', `phase7-lab-${run}`);
fs.mkdirSync(output, { recursive: true });
const pgEnv = {
  ...process.env,
  PGPASSWORD: decodeURIComponent(originalUrl.password),
};
const pgUser = decodeURIComponent(originalUrl.username);
function docker(args, input) {
  const result = spawnSync('docker', args, {
    env: pgEnv,
    input,
    maxBuffer: 64 * 1024 * 1024,
    windowsHide: true,
  });
  if (result.status !== 0)
    throw new Error(
      `Docker operation failed: ${args[0]} (details retained locally)`,
    );
  return result.stdout;
}
function pg(command, args, input) {
  return docker(
    [
      'exec',
      '-i',
      '-e',
      'PGPASSWORD',
      'ggvault-postgres',
      command,
      '-U',
      pgUser,
      ...args,
    ],
    input,
  );
}
const targetUrl = new URL(originalUrl);
targetUrl.pathname = '/' + database;
Object.assign(process.env, {
  DATABASE_URL: targetUrl.toString(),
  REDIS_URL: 'redis://127.0.0.1:6387',
  NODE_ENV: 'test',
  BETA_MODE: 'true',
  ENABLE_TEST_CREDITS: 'true',
  INITIAL_TEST_CREDITS: '100',
  PLATFORM_FEE_BPS: '500',
  EVIDENCE_STORAGE_DIR: path.join(output, 'evidence'),
});
const { verify } = require('../scripts/ledger-invariants.cjs');
let app,
  db,
  redisCreated = false;
const measurements = [];
const report = {
  run,
  database,
  started: new Date().toISOString(),
  results: {},
};
async function start() {
  const { NestFactory } = require('@nestjs/core');
  const { AppModule } = require('../apps/api/dist/app.module');
  const { configureApp } = require('../apps/api/dist/setup');
  const { PrismaService } = require('../apps/api/dist/database/prisma.service');
  app = await NestFactory.create(AppModule, { logger: false });
  configureApp(app);
  await app.listen(0, '127.0.0.1');
  db = app.get(PrismaService);
  return await app.getUrl();
}
let base;
async function request(route, actor, body, expected = [200, 201], key) {
  const start = performance.now();
  const response = await fetch(base + route, {
    method: body === undefined ? 'GET' : 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(actor ? { Authorization: 'Bearer ' + actor.accessToken } : {}),
      ...(key ? { 'Idempotency-Key': key } : {}),
    },
    body: body === undefined ? undefined : JSON.stringify(body),
    signal: AbortSignal.timeout(30000),
  });
  const data = await response.json();
  measurements.push({
    operation:
      (body === undefined ? 'GET ' : 'POST ') +
      route.replace(/c[a-z0-9]{24}/g, ':id').split('?')[0],
    ms: performance.now() - start,
    status: response.status,
    expected: expected.includes(response.status),
  });
  if (!expected.includes(response.status))
    throw new Error(
      `Unexpected ${response.status} for ${route.replace(/c[a-z0-9]{24}/g, ':id')}: ${data.code}`,
    );
  return { ...data, httpStatus: response.status };
}
let game;
async function player(index, role = 'USER') {
  const { AuthService } = require('../apps/api/dist/auth/auth.service');
  const user = await app.get(AuthService).register({
    username: `lab${run}${index}`,
    email: `lab${run}${index}@example.invalid`,
    password: 'Lab-only-strong-password-123!',
  });
  if (role !== 'USER')
    await db.user.update({ where: { id: user.user.id }, data: { role } });
  await db.gameAccount.create({
    data: {
      userId: user.user.id,
      gameId: game.id,
      platform: 'PS5',
      gamertag: `lab${index}`,
    },
  });
  return user;
}
async function create(a) {
  return request('/challenges', a, {
    gameId: game.id,
    stakeAmount: 10,
    currency: 'TEST',
    platform: 'PS5',
    mode: '1v1',
  });
}
async function funded(a, b) {
  const challenge = await create(a);
  await request(`/challenges/${challenge.id}/join`, b, {});
  await Promise.all(
    [a, b].map((actor) =>
      request(
        `/challenges/${challenge.id}/fund`,
        actor,
        {},
        [200],
        `fund-${challenge.id}`,
      ),
    ),
  );
  const match = await db.match.findUniqueOrThrow({
    where: { challengeId: challenge.id },
  });
  return { challenge, match };
}
async function result(a, b) {
  const value = await funded(a, b);
  const id = value.match.id;
  await Promise.all(
    [a, b].map((actor) => request(`/matches/${id}/ready`, actor, {})),
  );
  await request(`/matches/${id}/result`, a, { myScore: 4, opponentScore: 2 });
  return value;
}
async function snapshot() {
  const data = await db.$transaction(
    async (tx) => ({
      users: await tx.user.findMany({
        orderBy: { id: 'asc' },
        select: { id: true },
      }),
      entries: await tx.ledgerEntry.findMany({ orderBy: { id: 'asc' } }),
      transactions: await tx.ledgerTransaction.findMany({
        orderBy: { id: 'asc' },
      }),
      accounts: await tx.ledgerAccount.findMany({ orderBy: { id: 'asc' } }),
      challenges: await tx.challenge.findMany({ orderBy: { id: 'asc' } }),
      matches: await tx.match.findMany({ orderBy: { id: 'asc' } }),
      results: await tx.matchResult.findMany({ orderBy: { id: 'asc' } }),
      disputes: await tx.dispute.findMany({ orderBy: { id: 'asc' } }),
    }),
    { isolationLevel: 'RepeatableRead' },
  );
  return createHash('sha256').update(JSON.stringify(data)).digest('hex');
}
async function recovery() {
  const a = await player('a'),
    b = await player('b'),
    moderator = await player('mod', 'MODERATOR');
  await funded(a, b);
  const settled = await result(a, b);
  await request(`/matches/${settled.match.id}/result/confirm`, b, {});
  const disputed = await result(a, b);
  await request(`/matches/${disputed.match.id}/result/dispute`, b, {
    reason: 'Recovery fixture dispute',
  });
  const refunded = await result(a, b);
  await request(`/matches/${refunded.match.id}/result/dispute`, b, {
    reason: 'Recovery fixture refund',
  });
  const dispute = await db.dispute.findFirstOrThrow({
    where: { matchResult: { matchId: refunded.match.id } },
  });
  await request(`/moderation/disputes/${dispute.id}/resolve`, moderator, {
    resolution: 'VOID_MATCH',
    reason: 'Recovery fixture evidence reviewed',
  });
  const before = await snapshot();
  const invariant = await verify(db);
  if (!invariant.ok) throw new Error('Pre-backup invariant failed');
  await app.close();
  app = undefined;
  const backup = pg('pg_dump', [
    '-d',
    database,
    '-Fc',
    '--no-owner',
    '--no-acl',
  ]);
  fs.writeFileSync(path.join(output, 'recovery.dump'), backup);
  pg('dropdb', [database]);
  pg('createdb', [database]);
  pg(
    'pg_restore',
    ['-d', database, '--single-transaction', '--no-owner', '--no-acl'],
    backup,
  );
  base = await start();
  const after = await snapshot();
  if (before !== after) throw new Error('Restored state differs');
  await request('/health/ready');
  const restored = await verify(db);
  if (!restored.ok) throw new Error('Restored ledger invariant failed');
  report.results.recovery = {
    passed: true,
    exactStateHash: after,
    ...restored,
  };
  const { createClient } = require('redis');
  const redis = createClient({ url: process.env.REDIS_URL });
  redis.on('error', () => {});
  await redis.connect();
  await redis.set('ggvault:lab:session', 'ephemeral');
  await redis.quit();
  docker(['stop', redisName]);
  await request('/health/live');
  await request('/health/ready', undefined, undefined, [503]);
  if ((await snapshot()) !== after)
    throw new Error('PostgreSQL state changed during Redis outage');
  docker(['rm', redisName]);
  redisCreated = false;
  docker([
    'run',
    '-d',
    '--name',
    redisName,
    '-p',
    '127.0.0.1:6387:6379',
    'redis:7-alpine',
    'redis-server',
    '--save',
    '',
    '--appendonly',
    'no',
  ]);
  redisCreated = true;
  await request('/health/ready');
  const fresh = createClient({ url: process.env.REDIS_URL });
  fresh.on('error', () => {});
  await fresh.connect();
  const missing = await fresh.get('ggvault:lab:session');
  await fresh.quit();
  if (missing !== null || (await snapshot()) !== after)
    throw new Error('Redis loss behavior differs');
  report.results.redisLoss = {
    passed: true,
    ephemeralSessionLost: true,
    financialStateUnchanged: true,
  };
}
async function concurrency() {
  const a = await player('racea'),
    b = await player('raceb'),
    c = await player('racec'),
    mod = await player('racemod', 'MODERATOR');
  const challenge = await create(a);
  const joins = await Promise.all(
    [b, c].map((actor) =>
      request(`/challenges/${challenge.id}/join`, actor, {}, [200, 409]),
    ),
  );
  if (joins.filter((r) => r.httpStatus === 200).length !== 1)
    throw new Error('Final slot race failed');
  const opponent = joins[0].httpStatus === 200 ? b : c;
  await Promise.all(
    Array.from({ length: 4 }, () =>
      request(
        `/challenges/${challenge.id}/fund`,
        a,
        {},
        [200],
        'same-fund-key',
      ),
    ),
  );
  await request(
    `/challenges/${challenge.id}/fund`,
    opponent,
    {},
    [200],
    'opponent-fund-key',
  );
  const match = await db.match.findUniqueOrThrow({
    where: { challengeId: challenge.id },
  });
  await Promise.all(
    [a, a, opponent, opponent].map((actor) =>
      request(`/matches/${match.id}/ready`, actor, {}),
    ),
  );
  await request(`/matches/${match.id}/result`, a, {
    myScore: 4,
    opponentScore: 2,
  });
  await Promise.all([
    request(`/matches/${match.id}/result/confirm`, opponent, {}, [200, 409]),
    request(
      `/matches/${match.id}/result/dispute`,
      opponent,
      { reason: 'Concurrent decision fixture' },
      [200, 409],
    ),
  ]);
  const dispute = await db.dispute.findFirst({
    where: { matchResult: { matchId: match.id } },
  });
  if (dispute)
    await Promise.all(
      ['PLAYER_A_WINS', 'VOID_MATCH'].map((resolution) =>
        request(
          `/moderation/disputes/${dispute.id}/resolve`,
          mod,
          { resolution, reason: 'Concurrent settlement refund fixture' },
          [200, 409],
        ),
      ),
    );
  const refunds = await result(a, opponent);
  await request(`/matches/${refunds.match.id}/result/dispute`, opponent, {
    reason: 'Concurrent refund fixture',
  });
  const refundDispute = await db.dispute.findFirstOrThrow({
    where: { matchResult: { matchId: refunds.match.id } },
  });
  await Promise.all(
    Array.from({ length: 3 }, () =>
      request(
        `/moderation/disputes/${refundDispute.id}/resolve`,
        mod,
        { resolution: 'VOID_MATCH', reason: 'Duplicate refund regression' },
        [200, 409],
      ),
    ),
  );
  const check = await verify(db);
  const overfilled =
    await db.$queryRaw`SELECT "challengeId" FROM challenge_players GROUP BY "challengeId" HAVING COUNT(*) > 2`;
  const duplicate =
    await db.$queryRaw`SELECT "matchId" FROM ledger_transactions WHERE type IN ('MATCH_SETTLEMENT','STAKE_REFUND') GROUP BY "matchId" HAVING COUNT(*) > 1`;
  if (!check.ok || overfilled.length || duplicate.length)
    throw new Error('Concurrency invariant failed');
  report.results.concurrency = {
    passed: true,
    ...check,
    overfilled: overfilled.length,
    duplicateOutcomes: duplicate.length,
  };
}
async function load() {
  const vus = Number(process.env.LOAD_VUS ?? 20);
  const arrivalMs = Number(process.env.LOAD_ARRIVAL_MS ?? 500);
  if (!Number.isInteger(arrivalMs) || arrivalMs < 0 || arrivalMs > 10000)
    throw new Error('LOAD_ARRIVAL_MS must be 0..10000');
  if (!Number.isInteger(vus) || vus < 1 || vus > 1000)
    throw new Error('LOAD_VUS must be 1..1000');
  const actors = [];
  for (let i = 0; i < vus; i++)
    actors.push([
      await player('load' + i + 'a'),
      await player('load' + i + 'b'),
    ]);
  measurements.length = 0;
  const start = performance.now();
  const failures = await Promise.all(
    actors.map(async ([a, b], index) => {
      await new Promise((resolve) => setTimeout(resolve, index * arrivalMs));
      try {
        // A discovery, B creation/join, C concurrent funding, D ready/result/confirm, E mixture.
        await request('/challenges?limit=20', a);
        const value = await result(a, b);
        await request(`/matches/${value.match.id}/result/confirm`, b, {});
        await request('/users/me/transactions', a);
        await request('/matches', b);
        return false;
      } catch {
        return true;
      }
    }),
  );
  const seconds = (performance.now() - start) / 1000;
  const groups = {};
  for (const row of measurements) (groups[row.operation] ??= []).push(row);
  const metrics = Object.fromEntries(
    Object.entries(groups).map(([operation, rows]) => {
      const sorted = rows.map((r) => r.ms).sort((a, b) => a - b);
      const p = (q) =>
        Math.round(
          sorted[Math.max(0, Math.ceil(sorted.length * q) - 1)] * 100,
        ) / 100;
      return [
        operation,
        {
          requests: rows.length,
          p50: p(0.5),
          p95: p(0.95),
          p99: p(0.99),
          errorRate: rows.filter((r) => !r.expected).length / rows.length,
        },
      ];
    }),
  );
  const invariant = await verify(db);
  report.results.load = {
    vus,
    arrivalMs,
    seconds,
    requests: measurements.length,
    requestsPerSecond: measurements.length / seconds,
    failedFlows: failures.filter(Boolean).length,
    errorRate:
      measurements.filter((r) => !r.expected).length / measurements.length,
    operations: metrics,
    invariant,
  };
  if (!invariant.ok) throw new Error('Load invariant failed');
  const discoveryVus = Number(process.env.LOAD_DISCOVERY_VUS ?? 100);
  if (
    !Number.isInteger(discoveryVus) ||
    discoveryVus < 1 ||
    discoveryVus > 1000
  )
    throw new Error('LOAD_DISCOVERY_VUS must be 1..1000');
  measurements.length = 0;
  const discoveryStart = performance.now();
  await Promise.all(
    Array.from({ length: discoveryVus }, (_, i) =>
      request('/challenges?limit=20', actors[i % actors.length][0]),
    ),
  );
  const times = measurements.map((row) => row.ms).sort((a, b) => a - b);
  report.results.discovery = {
    vus: discoveryVus,
    requests: times.length,
    requestsPerSecond:
      times.length / ((performance.now() - discoveryStart) / 1000),
    p50: times[Math.ceil(times.length * 0.5) - 1],
    p95: times[Math.ceil(times.length * 0.95) - 1],
    p99: times[Math.ceil(times.length * 0.99) - 1],
    errorRate: 0,
  };
  const userId = actors[0][0].user.id;
  const account = await db.ledgerAccount.findFirstOrThrow({
    where: { userId, accountType: 'USER_AVAILABLE' },
  });
  const plans = {
    creator:
      await db.$queryRaw`EXPLAIN (ANALYZE, FORMAT JSON) SELECT count(*) FROM challenges WHERE "createdByUserId"=${userId} AND status='OPEN'`,
    history:
      await db.$queryRaw`EXPLAIN (ANALYZE, FORMAT JSON) SELECT id FROM ledger_entries WHERE "ledgerAccountId"=${account.id} ORDER BY "createdAt",id LIMIT 20`,
    discovery:
      await db.$queryRaw`EXPLAIN (ANALYZE, FORMAT JSON) SELECT id FROM challenges WHERE status='OPEN' ORDER BY id LIMIT 20`,
  };
  fs.writeFileSync(
    path.join(output, 'query-plans.json'),
    JSON.stringify(plans, null, 2),
  );
  if (failures.some(Boolean)) {
    report.loadThresholdFailed = true;
    process.exitCode = 1;
  }
}
(async () => {
  try {
    pg('createdb', [database]);
    docker([
      'run',
      '-d',
      '--name',
      redisName,
      '-p',
      '127.0.0.1:6387:6379',
      'redis:7-alpine',
      'redis-server',
      '--save',
      '',
      '--appendonly',
      'no',
    ]);
    redisCreated = true;
    const migrate = spawnSync(
      process.execPath,
      [
        require.resolve('prisma/build/index.js'),
        'migrate',
        'deploy',
        '--schema',
        'packages/database/prisma/schema.prisma',
      ],
      { cwd: root, env: process.env, encoding: 'utf8', windowsHide: true },
    );
    if (migrate.status !== 0) throw new Error('Lab migration failed');
    base = await start();
    game = await db.game.create({
      data: { name: 'FC 26', slug: 'fc26', enabled: true },
    });
    await recovery();
    await concurrency();
    await load();
  } catch (error) {
    report.error = error.message;
    process.exitCode = 1;
  } finally {
    if (app) await app.close();
    if (redisCreated) docker(['rm', '-f', redisName]);
    report.finished = new Date().toISOString();
    fs.writeFileSync(
      path.join(output, 'report.json'),
      JSON.stringify(report, null, 2),
    );
    console.log(
      JSON.stringify({
        report: path.join(output, 'report.json'),
        results: report.results,
        error: report.error,
      }),
    );
    // Keep only this generated disposable database for inspection; never touch the source database.
  }
})();
